
<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { Search, View, Check, Van, CircleCheck, Close } from '@element-plus/icons-vue'
import { adminOrderApi, riderApi } from '@/api'
import type { Order, PageData, Rider } from '@/types'
import { dateTime, money, orderStatusType, statusOptions } from '@/utils'
const router=useRouter();const data=ref<PageData<Order>>({records:[],current:1,size:10,total:0,pages:0});const query=reactive({page:1,size:10,orderNo:'',keyword:'',orderStatus:'',riderId:undefined as number|undefined});const riders=ref<Rider[]>([]);const dispatchDialog=ref(false);const selectedOrder=ref<Order>();const dispatch=reactive({riderId:undefined as number|undefined,adminRemark:'已安排骑手配送'});
const load=async(page=query.page)=>{query.page=page;data.value=await adminOrderApi.page({...query,orderStatus:query.orderStatus||undefined})};onMounted(async()=>{riders.value=await riderApi.available();await load()})
const action=async(order:Order,type:string)=>{if(type==='dispatch'){selectedOrder.value=order;dispatch.riderId=undefined;dispatch.adminRemark='已安排骑手配送';dispatchDialog.value=true;return}if(type==='cancel'){const {value}=await ElMessageBox.prompt('请输入取消原因','取消订单',{inputValidator:v=>v?true:'请输入取消原因',type:'warning'});await adminOrderApi.cancel(order.id,value)}else{const labels:any={accept:'确认接单并进入待打包？',pack:'确认药品已打包完成？',complete:'确认订单已送达？'};await ElMessageBox.confirm(labels[type],'订单操作',{type:'warning'});if(type==='accept')await adminOrderApi.accept(order.id,'已接单，开始备货');if(type==='pack')await adminOrderApi.pack(order.id,'药品已打包完成');if(type==='complete')await adminOrderApi.complete(order.id,'已确认送达')}ElMessage.success('操作成功');await load(data.value.current)}
const submitDispatch=async()=>{if(!selectedOrder.value||!dispatch.riderId)return ElMessage.warning('请选择可接单骑手');await adminOrderApi.dispatch(selectedOrder.value.id,dispatch);ElMessage.success('已派单，订单进入配送中');dispatchDialog.value=false;await load(data.value.current)}
const reset=()=>{Object.assign(query,{page:1,orderNo:'',keyword:'',orderStatus:'',riderId:undefined});load(1)}
</script>
<template><div><div class="admin-page-head"><div><span class="eyebrow">ORDER FULFILLMENT</span><h1>订单管理</h1><p>按状态推进接单、打包、派单和完成配送。</p></div><el-button @click="load(data.current)">刷新订单</el-button></div><section class="control-card table-card"><div class="filter-row order-filter"><el-input v-model="query.orderNo" placeholder="订单号" :prefix-icon="Search" clearable/><el-input v-model="query.keyword" placeholder="收货人/手机号/用户名" :prefix-icon="Search" clearable/><el-select v-model="query.orderStatus" placeholder="全部状态" clearable><el-option v-for="[v,l] in statusOptions" :key="v" :label="l" :value="v"/></el-select><el-select v-model="query.riderId" placeholder="全部骑手" clearable><el-option v-for="r in riders" :key="r.id" :label="r.riderName" :value="r.id"/></el-select><el-button type="primary" @click="load(1)">查询</el-button><el-button @click="reset">重置</el-button></div><el-table :data="data.records" stripe><el-table-column label="订单号 / 下单时间" min-width="195"><template #default="{row}"><b class="order-no">{{row.orderNo}}</b><small class="time">{{dateTime(row.createTime)}}</small></template></el-table-column><el-table-column label="收货信息" min-width="180"><template #default="{row}"><b>{{row.receiverName}} {{row.receiverPhone}}</b><small class="addr">{{row.receiverAddress}}</small></template></el-table-column><el-table-column label="金额" width="100"><template #default="{row}"><b class="price">{{money(row.orderAmount)}}</b></template></el-table-column><el-table-column label="状态" width="105"><template #default="{row}"><el-tag :type="orderStatusType(row.orderStatus)" round>{{row.orderStatusName}}</el-tag></template></el-table-column><el-table-column label="骑手" width="115"><template #default="{row}"><span v-if="row.riderName">{{row.riderName}}</span><span v-else class="muted">未派单</span></template></el-table-column><el-table-column label="操作" width="285" fixed="right"><template #default="{row}"><el-button text type="primary" :icon="View" @click="router.push(`/admin/orders/${row.id}`)">详情</el-button><el-button v-if="row.orderStatus==='PENDING_ACCEPT'" text type="primary" :icon="Check" @click="action(row,'accept')">接单</el-button><el-button v-if="row.orderStatus==='TO_PACK'" text type="warning" :icon="Check" @click="action(row,'pack')">打包</el-button><el-button v-if="row.orderStatus==='TO_DISPATCH'" text type="primary" :icon="Van" @click="action(row,'dispatch')">派单</el-button><el-button v-if="row.orderStatus==='DELIVERING'" text type="success" :icon="CircleCheck" @click="action(row,'complete')">完成</el-button><el-button v-if="['PENDING_ACCEPT','TO_PACK','TO_DISPATCH'].includes(row.orderStatus)" text type="danger" :icon="Close" @click="action(row,'cancel')">取消</el-button></template></el-table-column></el-table></section><div class="pagination"><el-pagination background layout="total, prev, pager, next" :current-page="data.current" :page-size="data.size" :total="data.total" @current-change="load"/></div><el-dialog v-model="dispatchDialog" title="派单并开始配送" width="min(460px,92%)"><p class="dialog-tip">订单：{{selectedOrder?.orderNo}}，请选择当前可接单骑手。</p><el-form label-position="top"><el-form-item label="配送骑手" required><el-select v-model="dispatch.riderId" placeholder="请选择骑手" style="width:100%"><el-option v-for="r in riders" :key="r.id" :label="`${r.riderName} · ${r.phone}`" :value="r.id"/></el-select></el-form-item><el-form-item label="管理员备注"><el-input v-model="dispatch.adminRemark" maxlength="255"/></el-form-item></el-form><template #footer><el-button @click="dispatchDialog=false">取消</el-button><el-button type="primary" @click="submitDispatch">确认派单</el-button></template></el-dialog></div></template>
<style scoped>.eyebrow{font-size:11px;color:#1677ff;letter-spacing:2px;font-weight:700}.admin-page-head h1{font-size:27px;margin:6px 0}.admin-page-head p{margin:0;color:#8491a4;font-size:13px}.order-filter .el-input{width:180px}.order-filter .el-select{width:135px}.order-no,.time,.addr{display:block}.order-no{font-size:12px;color:#405168}.time,.addr{font-size:10px;color:#96a3b2;margin-top:4px}.addr{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:190px}.price{color:#ff6d2c}.muted{font-size:12px;color:#a0adbc}.dialog-tip{font-size:12px;color:#74849a;margin-top:-8px}@media(max-width:700px){.order-filter .el-input{width:100%;flex-basis:100%}}</style>
